fn encode(message: Vec<char>) -> Vec<char> {
    // Helper function to determine if a character is a vowel (uppercase or lowercase)
    fn is_vowel(c: char) -> bool {
        matches!(c, 'a' | 'e' | 'i' | 'o' | 'u' |
                    'A' | 'E' | 'I' | 'O' | 'U')
    }

    // Helper function to map vowel according to the given mapping
    fn map_vowel(c: char) -> char {
        match c {
            'a' => 'c', 'e' => 'g', 'i' => 'k', 'o' => 'q', 'u' => 'w',
            'A' => 'C', 'E' => 'G', 'I' => 'K', 'O' => 'Q', 'U' => 'W',
            _ => c, // Should never occur, but keep c as fallback
        }
    }

    // Helper function to swap the case of a letter
    fn swap_case(c: char) -> char {
        if c.is_uppercase() {
            c.to_ascii_lowercase()
        } else {
            c.to_ascii_uppercase()
        }
    }

    // Process each character independently according to the rules
    message
        .into_iter()
        .map(|c| {
            if c == ' ' {
                // Space remains space
                ' '
            } else if is_vowel(c) {
                // For vowels: first map, then swap case
                let mapped = map_vowel(c);
                swap_case(mapped)
            } else {
                // For consonants: just swap case
                swap_case(c)
            }
        })
        .collect()
}